// Client reset queue and borrowed entity ID map; not full network world.
class MCReset027 {I32 x,y,z,delay,id,meta;};class MCRemoteEntity027 {I32 id;Entity *entity;};
class MultiPlayerLevel {Level *level;MCVector resets,entities;MCPtrVector retries;Bool daylightCycle;};
U0 MultiPlayerLevel_Init(MultiPlayerLevel *s,Level *l){memset(s,0,sizeof(MultiPlayerLevel));s->level=l;s->daylightCycle=TRUE;MCVector_Init(&s->resets,sizeof(MCReset027));MCVector_Init(&s->entities,sizeof(MCRemoteEntity027));MCPtrVector_Init(&s->retries);}
U0 MultiPlayerLevel_Destroy(MultiPlayerLevel *s){MCVector_Destroy(&s->resets);MCVector_Destroy(&s->entities);MCPtrVector_Destroy(&s->retries);}
Entity *MultiPlayerLevel_getEntity(MultiPlayerLevel *s,I32 id){I32 i;for(i=0;i<s->entities.size;i++){MCRemoteEntity027 *r=MCVector_At(&s->entities,i);if(r->id==id)return r->entity;}return NULL;}
U0 MultiPlayerLevel_putEntity(MultiPlayerLevel *s,I32 id,Entity *e){if(!e)return;I32 i;for(i=0;i<s->entities.size;i++){MCRemoteEntity027 *r=MCVector_At(&s->entities,i);if(r->id==id){if(r->entity!=e)Level_removeEntity(s->level,&r->entity->body);r->entity=e;e->body.id=id;Level_addEntity(s->level,&e->body);return;}}MCRemoteEntity027 r;r.id=id;r.entity=e;e->body.id=id;MCVector_Push(&s->entities,&r);Level_addEntity(s->level,&e->body);}
U0 MultiPlayerLevel_removeEntity(MultiPlayerLevel *s,I32 id){I32 i;for(i=0;i<s->entities.size;i++){MCRemoteEntity027 *r=MCVector_At(&s->entities,i);if(r->id==id){Level_removeEntity(s->level,&r->entity->body);MCVector_Erase(&s->entities,i);return;}}}
Bool MultiPlayerLevel_resetLater(MultiPlayerLevel *s,I32 x,I32 y,I32 z,I32 delay,I32 id,I32 meta){if(delay<=0 || id<0 || id>255 || !Level_InBounds(x,y,z))return FALSE;MCReset027 r;r.x=x;r.y=y;r.z=z;r.delay=delay;r.id=id;r.meta=meta;MCVector_Push(&s->resets,&r);return TRUE;}
U0 MultiPlayerLevel_tick(MultiPlayerLevel *s){if(!s->level->world.isClient){Level_tick(s->level);return;}if(s->daylightCycle)s->level->data.time++;I32 i;for(i=0;i<s->resets.size;i++){MCReset027 *r=MCVector_At(&s->resets,i);r->delay--;if(!r->delay){Level_setTileAndData(s->level,r->x,r->y,r->z,r->id,r->meta,2);MCVector_Erase(&s->resets,i);i--;}}/* Source retry-set UB is not copied. Explicit body index inserts are immediate in finite Level025. */}
